#!/usr/bin/env bash
# Lägger varje väntande rytmpatch som egen gren och egen pull request (F31).
# AI-skapat (B-051). Generated by AI, Directed by MS.
#
# Användning: scripts/lagg-rytmpatchar.sh rytmpatchar/
#   Varje fil <gren>.patch i mappen blir grenen <gren> från main och en PR mot main.
#   PR-texten läses från <gren>.md om den finns.
# Skriptet slår aldrig ihop, driftsätter aldrig och rör inga hemligheter eller inställningar.
# Finns grenen redan på origin hoppas patchen över (körningen kan upprepas utan dubbletter).
set -euo pipefail

mapp="${1:?Ange mappen med .patch-filer}"
git fetch -q origin main

for patch in "$mapp"/*.patch; do
  [ -e "$patch" ] || { echo "Inga patchar i $mapp"; exit 0; }
  gren="$(basename "$patch" .patch)"
  if git ls-remote --exit-code --heads origin "$gren" >/dev/null 2>&1; then
    echo "Hoppar över $gren: grenen finns redan på origin"
    continue
  fi
  git switch -q -C "$gren" origin/main
  if ! git am -q --3way "$patch"; then
    git am --abort || true
    echo "Kunde inte lägga $gren: patchen går inte att applicera på main" >&2
    continue
  fi
  git push -q -u origin "$gren"
  titel="$(git log -1 --format=%s)"
  text="$mapp/$gren.md"
  if [ -f "$text" ]; then
    gh pr create --base main --head "$gren" --title "$titel" --body-file "$text"
  else
    gh pr create --base main --head "$gren" --title "$titel" \
      --body "Rytmpatch $gren. AI-skapat (B-051). Generated by AI, Directed by MS. Ingen sammanslagning utan Mattias ja."
  fi
done
git switch -q main
